exercises.solutionCode:
#include <stdint.h>

typedef struct {
    const char *name;
    int mhz;
    int flash_kb;
    int sram_kb;
} McuSpec;

int find_first_match(const McuSpec *list, int n,
                     int min_mhz, int min_flash_kb, int min_sram_kb)
{
    if (list == NULL || n <= 0) {
        return -1;
    }

    for (int i = 0; i < n; i++) {
        const McuSpec *s = &list[i];

        if (s->mhz < 0 || s->flash_kb < 0 || s->sram_kb < 0) {
            continue;
        }
        if (s->mhz >= min_mhz && s->flash_kb >= min_flash_kb && s->sram_kb >= min_sram_kb) {
            return i;
        }
    }
    return -1;
}
